//! Virtual Machine for executing compiled Verilog-A bytecode.
//!
//! This module provides a stack-based VM that executes bytecode programs
//! generated by the code generator. It handles voltage/current access,
//! parameter lookup, and mathematical operations.

mod context;
mod error;
mod executor;
mod filters;
mod small_signal;

pub(crate) use context::idtmod_wrapped_value;
pub use context::{
    CURRENT_PAIR_GROUND, IntegrationCoefficients, VerilogAEvaluationMode, VmAcceptedCheckpoint,
    VmContext, terminal_pair_current_endpoints, terminal_pair_current_index,
    terminal_pair_current_len,
};
#[cfg(feature = "native")]
pub(crate) use context::{
    LIMITER_HISTORY_UNINITIALIZED, LIMITER_HISTORY_VALID, pin_limiter_history,
};
pub use error::VmError;
pub use executor::Vm;
#[cfg(feature = "native")]
pub(crate) use executor::observe_zi_state;
#[cfg(all(feature = "wasm-jit", any(target_arch = "wasm32", test)))]
pub(crate) use executor::{execute_zi_state, execute_zi_state_derivative};
pub(crate) use filters::{
    CrossCheckpoint, DelayCheckpoint, DelayConfiguration, PendingTransitionCheckpoint,
    SlewCheckpoint, TransitionCheckpoint, TransitionSegmentCheckpoint, timer_event_evaluation,
};
pub use filters::{CrossDetector, DelayBuffer, SlewFilter, TransitionFilter};
pub use rspice_veriloga_runtime::AnalogAnalysisPhase;
pub(crate) use small_signal::SmallSignalVm;
